    template <typename L, typename R>                                          \
        requires HasReactOp<L, R>                                              \
    constexpr auto operator op_symbol(L &&l, R &&r) {                          \
        return make_binary_op<OpType>(std::forward<L>(l), std::forward<R>(r)); \
    }

