    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseOrAssignable<Type, U>)
    React &operator|=(const U &rhs) {
        atomicBitwiseOrAssign(*getPtr(), rhs);
        return *this;
