    template <typename T = MutexType>
    auto lock_shared() noexcept(noexcept(std::declval<T>().lock_shared()))
        -> decltype(std::declval<T>().lock_shared(), void()) {
        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
