        if (!node) return;

        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);

        // Step 1: Save current state for rollback
        NodeSet originalDependents;
        if (m_dependentList.contains(node)) {
            originalDependents = m_dependentList[node];
