public:
    ScopedValue(T &target, T newValue)
        : ref_(target), old_(target) {
        ref_ = std::move(newValue);
    }

    ~ScopedValue() {
        ref_ = std::move(old_);
    }

    ScopedValue(const ScopedValue &) = delete;
    ScopedValue &operator=(const ScopedValue &) = delete;

