    void triggerCleanup() noexcept {
        triggerCleanupInternal();
    }

private:
    static constexpr size_t MAX_CACHE_SIZE = 500;       // Smaller cache for immediate observers only
    static constexpr std::chrono::minutes CACHE_TTL{5}; // Shorter TTL
};

/**
