            }
            if (!m_observerList.contains(target)) {
                addNodeInternal(target);
            }
        }

        if (hasCycle(source, target)) {
            REACTION_THROW_DEPENDENCY_CYCLE(getNameInternal(source), getNameInternal(target));
        }

