class ConditionalMutexWrapper {
public:
    /// @brief Acquire lock if thread safety is enabled.
    void lock() noexcept(noexcept(std::declval<MutexType>().lock())) {
        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
            m_mutex.lock();
        }
    }

