     */
    [[nodiscard]] bool isUsingSBO() const noexcept {
        return false;
    }

protected:
    mutable ConditionalSharedMutex m_resourceMutex; ///< Conditional mutex for thread-safe resource access.
    std::unique_ptr<Type> m_ptr;                    ///< Unique pointer managing the resource
};

