    static std::string formatMessage(const std::string &message,
        ErrorCode code,
        const std::string &file,
        int line,
        const std::string &function) {
        std::ostringstream oss;
        oss << "[" << errorCodeToString(code) << "] " << message;

        if (!file.empty() || line > 0 || !function.empty()) {
            oss << " (";
            if (!function.empty()) {
