        if (m_cacheEntries.size() > m_maxCacheSize) {
            auto oldestIt = std::min_element(m_cacheEntries.begin(), m_cacheEntries.end(),
                [](const auto &a, const auto &b) {
                    return a.second.lastAccess < b.second.lastAccess;
